// Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
// keygen <client_home>
// Generates context + keys. SECRET KEY IS WRITTEN ONLY TO THE CLIENT HOME.
// The harness later gives the server home the context and relinearization key.
#include "common.hpp"
#include <iostream>

int main(int argc, char** argv) try {
    if (helpRequested(argc, argv)) {
        std::cout << "usage: keygen <client_home>\n\nStage 1 of 4 (client). Creates the CKKS context, the public, relinearization\nand secret keys, and writes them to <client_home>. The secret key stays there.\n";
        return 0;
    }
    std::string home = argc > 1 ? argv[1] : "client_home";

    auto cc = GenCryptoContext(designParams());
    cc->Enable(PKE);
    cc->Enable(KEYSWITCH);
    cc->Enable(LEVELEDSHE);
    cc->Enable(ADVANCEDSHE);  // EvalChebyshevSeries

    if (cc->GetRingDimension() != RING_DIM)
        throw std::runtime_error("ring dimension mismatch: got " +
                                 std::to_string(cc->GetRingDimension()));

    auto keys = cc->KeyGen();
    cc->EvalMultKeyGen(keys.secretKey);  // relinearization; NO rotation keys needed

    mustSerialize(cc, home + "/context.bin");
    mustSerialize(keys.publicKey, home + "/key_public.bin");
    mustSerialize(keys.secretKey, home + "/key_secret.bin");
    {
        std::ofstream f(home + "/key_relin.bin", std::ios::binary);
        if (!cc->SerializeEvalMultKey(f, SerType::BINARY))
            throw std::runtime_error("Cannot serialize relin key");
    }
    std::cout << "keygen: N=" << cc->GetRingDimension()
              << " depth=" << MULT_DEPTH << " scale=" << SCALE_BITS
              << "\n  context.bin    " << fileSize(home + "/context.bin")
              << "\n  key_public.bin " << fileSize(home + "/key_public.bin")
              << "\n  key_relin.bin  " << fileSize(home + "/key_relin.bin")
              << "\n  key_secret.bin " << fileSize(home + "/key_secret.bin")
              << " (client only)\n";
    return 0;
} catch (const std::exception& e) {
    std::cerr << "keygen: error: " << e.what() << "\n";
    return 1;
}
